--- /dev/null
+++ b/infra/providers.tf
@@ -1,0 +1,17 @@
+terraform {
+  required_version = ">= 1.11"
+
+  required_providers {
+    aws = {
+      source  = "hashicorp/aws"
+      version = "6.73.0"
+    }
+  }
+
+  # Sem backend remoto ainda: crie o bucket com o bootstrap (tela Infraestrutura, State) e cole aqui o bloco backend "s3".
+}
+
+provider "aws" {
+  region  = var.aws_region
+  profile = var.aws_profile
+}

--- /dev/null
+++ b/infra/resource.tf
@@ -1,0 +1,50 @@
+# ------------------------- Environment guard -------------------
+# O ambiente é o workspace selecionado; no workspace default os recursos não teriam ambiente definido.
+resource "terraform_data" "environment_guard" {
+  input = terraform.workspace
+
+  lifecycle {
+    precondition {
+      condition     = terraform.workspace != "default"
+      error_message = "Selecione o workspace do ambiente antes do plan/apply (ex.: tofu workspace select dev)."
+    }
+  }
+}
+
+locals {
+  name_prefix = "eventos-${terraform.workspace}"
+
+  tags = {
+    Project     = "eventos"
+    Environment = terraform.workspace
+    ManagedBy   = "terraform"
+  }
+}
+
+# ------------------------- SNS ---------------------------------
+module "sns" {
+  source = "./modules/sns"
+
+  name_prefix = local.name_prefix
+  alarm_email = var.alarm_email
+  tags        = local.tags
+}
+
+# ------------------------- SQS ---------------------------------
+module "sqs" {
+  source = "./modules/sqs"
+
+  name_prefix = local.name_prefix
+  flows       = ["notas-fiscais"]
+  tags        = local.tags
+}
+
+# ------------------------- CLOUDWATCH --------------------------
+module "cloudwatch" {
+  source = "./modules/cloudwatch"
+
+  name_prefix = local.name_prefix
+  topic_arn   = module.sns.topic_arn
+  flows       = ["notas-fiscais"]
+  tags        = local.tags
+}

--- /dev/null
+++ b/infra/output.tf
@@ -1,0 +1,9 @@
+output "alarm_topic_arn" {
+  description = "ARN do tópico SNS que recebe os alarmes"
+  value       = module.sns.topic_arn
+}
+
+output "queues" {
+  description = "Filas por fluxo: URL e ARN da fila principal e da fila de mensagens mortas"
+  value       = module.sqs.queues
+}

--- /dev/null
+++ b/infra/modules/sns/variables.tf
@@ -1,0 +1,23 @@
+# ------------------------- Environment -------------------------
+variable "name_prefix" {
+  description = "Prefixo dos nomes: <projeto>-<ambiente>"
+  type        = string
+
+  validation {
+    condition     = can(regex("^[a-z0-9-]+$", var.name_prefix))
+    error_message = "O prefixo deve conter apenas letras minúsculas, dígitos e hífens."
+  }
+}
+
+variable "alarm_email" {
+  description = "E-mail que recebe os alarmes; sem ele, o tópico existe e não há assinatura"
+  type        = string
+  default     = null
+}
+
+# ------------------------- Tags --------------------------------
+variable "tags" {
+  description = "Tags aplicadas aos recursos"
+  type        = map(string)
+  default     = {}
+}

