--- /dev/null
+++ b/infra/modules/sqs/outputs.tf
@@ -1,0 +1,11 @@
+output "queues" {
+  description = "Filas por fluxo: URL e ARN da fila principal e da fila de mensagens mortas"
+  value = {
+    for key, queue in aws_sqs_queue.main : key => {
+      url      = queue.url
+      arn      = queue.arn
+      dlq_arn  = aws_sqs_queue.dlq[key].arn
+      dlq_name = aws_sqs_queue.dlq[key].name
+    }
+  }
+}
